'use strict';
const V27Reliability={
 async corrections(){const r=await API.request('/v27/corrections');Router.page('装车与正式出库更正',`<div class="business-toolbar">${Business.can('load:write')?'<button id="v27-new-correction" class="button primary">新建装车或出库更正</button>':''}</div><div class="business-table"><table><thead><tr><th>更正单号</th><th>原装车单</th><th>处理类型</th><th>状态</th><th>操作</th></tr></thead><tbody>${r.items.map(c=>`<tr><td data-no-i18n>${esc(c.code)}</td><td data-no-i18n>${esc(c.original_snapshot.code)}</td><td>${this.kind(c.kind)}</td><td>${this.status(c.status)}</td><td><a href="/outbounds/corrections/${c.id}">查看详情</a></td></tr>`).join('')}</tbody></table></div>`);if($('v27-new-correction'))$('v27-new-correction').onclick=()=>this.createCorrection();},
 kind(k){return {CANCEL_LOAD:'授权装车撤销',RETURN_OUTBOUND:'正式出库返场冲销',VEHICLE:'车辆信息关联更正'}[k]||k;},status(s){return {REQUESTED:'待授权',AUTHORIZED:'已授权待核验',RETURN_VERIFIED:'实物退回已核验',APPLIED:'已生效',REJECTED:'已驳回'}[s]||s;},severity(s){return {CRITICAL:'严重',HIGH:'高风险',WARNING:'提示'}[s]||s;},findingName(s){return {DUPLICATE_BUNDLE:'捆包编号冲突',HISTORICAL_SEAL_CONFLICT:'历史铅封归属冲突',DOUBLE_RESERVATION:'重复有效备货占用',OUTBOUND_STILL_RESERVED:'已出库仍被锁定',WEIGHT_RULE_MISMATCH:'净重规则差异',FORMAL_CUSTOMER_MIX:'正式货位客户混放',FORMAL_LOT_OVERLAP:'正式货位批次占用冲突',PLAN_OVER_LIMIT:'销售计划超限',PLAN_CONTROLS_MISSING:'旧计划控制字段待补齐',EFFECTIVE_DOUBLE_OUTBOUND:'重复有效正式出库',POSTED_LOAD_ASSOCIATION:'正式出库关联缺失',UNPOSTED_ADJUSTMENT_LINK:'归档盘点调整未生效',CLOSED_PLAN_NOT_FULFILLED:'已关闭计划履约差异'}[s]||s;},
 async createCorrection(){const [loads,m]=await Promise.all([API.request('/loads'),Business.load()]);dialog('新建装车或出库更正',`<form id="v27-correction-create" class="user-form"><label>关联装车单<select name="loading_id" required>${loads.items.filter(l=>!['CANCELLED','REVERSED'].includes(l.status)).map(l=>`<option data-no-i18n value="${l.id}">${esc(l.code+' · '+l.vehicle_no)}</option>`).join('')}</select></label><label>处理类型<select name="kind"><option value="CANCEL_LOAD">授权装车撤销</option><option value="RETURN_OUTBOUND">正式出库返场冲销</option><option value="VEHICLE">车辆信息关联更正</option></select></label><label>退回临时堆存区<select name="return_location_id">${Business.options(m.locations.filter(l=>l.active&&l.map_usage==='TEMPORARY'),null,'code')}</select></label><label>更正后车牌<input name="vehicle_no" maxlength="80"></label><label class="check-label"><input name="physical_return_verified" type="checkbox">确认实物退回，待独立现场核验</label><label>实物核查依据<textarea name="physical_evidence" minlength="5" maxlength="1000"></textarea></label><label>更正依据<textarea name="reason" required minlength="5" maxlength="2000"></textarea></label><p>正式出库原单不删除。返场冲销必须经授权、实物核验及最终记账。</p><p id="v27-correction-error" class="error"></p><button class="button primary">提交更正申请</button></form>`);$('v27-correction-create').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{const b=Object.fromEntries(new FormData(e.target)),load=loads.items.find(l=>l.id===b.loading_id);const c=await API.request('/v27/corrections',{method:'POST',body:{loading_id:b.loading_id,version:load.version,kind:b.kind,reason:b.reason,details:{return_location_id:b.return_location_id,vehicle_no:b.vehicle_no,physical_return_verified:b.physical_return_verified==='on',physical_evidence:b.physical_evidence}}});$('dialog').close();await Router.go('/outbounds/corrections/'+c.id);}catch(err){$('v27-correction-error').textContent=err.message;e.submitter.disabled=false;}};},
 async correction(id){const c=await API.request('/v27/corrections/'+id);Router.page('更正记录 · '+c.code,`<p>${this.kind(c.kind)} · ${this.status(c.status)}</p><p data-no-i18n>${esc(c.reason)}</p><a href="/outbounds/loads/${c.loading_id}">查看原装车与出库单</a><details><summary>原始单据及捆包证据</summary><pre data-no-i18n>${esc(JSON.stringify({original:c.original_snapshot,bundles:c.bundle_snapshot,proposed:c.proposed_data},null,2))}</pre></details><div class="business-toolbar">${Business.can('outbound:approve')&&c.status==='REQUESTED'?'<button data-v27-correction-action="authorize">授权更正</button>':''}${Business.can('load:review')&&c.requested_by!==CurrentUser.id&&c.status==='AUTHORIZED'&&c.kind!=='VEHICLE'?'<button data-v27-correction-action="verify-return">确认实物退回核验</button>':''}${Business.can('outbound:approve')&&(c.status==='RETURN_VERIFIED'||c.status==='AUTHORIZED'&&c.kind==='VEHICLE')?'<button data-v27-correction-action="apply">执行授权更正</button>':''}${Business.can('outbound:approve')&&['REQUESTED','AUTHORIZED','RETURN_VERIFIED'].includes(c.status)?'<button data-v27-correction-action="reject">驳回更正</button>':''}</div><p id="v27-correction-action-error" class="error"></p><h2>更正审批历史</h2>${c.steps.map(s=>`<p><span data-no-i18n>${esc(s.occurred_at)} · ${esc(s.actor_name)}</span> · ${esc({REQUEST:'申请更正',authorize:'授权更正','verify-return':'实物退回核验',apply:'执行授权更正',reject:'驳回更正'}[s.action]||s.action)} · <span data-no-i18n>${esc(s.reason)}</span></p>`).join('')}`);for(const b of document.querySelectorAll('[data-v27-correction-action]'))b.onclick=()=>V27Counts.reasonForm(b.textContent,async reason=>{await API.request('/v27/corrections/'+id+'/'+b.dataset.v27CorrectionAction,{method:'POST',body:{version:c.version,reason}});await Router.go('/outbounds/corrections/'+id);});},
 auditAction(code){return {export_transport_updated:'出口运输资料修改',packing_list_generated:'生成Packing List',login:'用户登录',logout:'用户退出',operation_failed:'操作失败',consistency_scan:'一致性检查',stocktake_drafted:'盘点草稿',stocktake_observed:'录入实盘结果',stocktake_start:'开始盘点','stocktake_submit-review':'提交差异复核',stocktake_review:'复核通过',stocktake_approve:'审批通过',stocktake_resolution:'差异处理',stocktake_complete:'完成并归档',stocktake_cancel:'取消任务',outbound_correction_request:'申请更正',outbound_correction_authorize:'授权更正','outbound_correction_verify-return':'实物退回核验',outbound_correction_apply:'执行授权更正',role_permissions_changed:'角色权限修改',inventory_export:'库存导出'}[code]||'业务操作';},
 async audit(){const q=new URLSearchParams(location.search),[r,backups]=await Promise.all([API.request('/v27/audit?'+q),Business.can('system:manage')?API.request('/v27/backups'):Promise.resolve({items:[]})]);Router.page('系统日志',`<form id="v27-audit-filter" class="business-toolbar"><label>操作类型<input name="action" value="${esc(q.get('action')||'')}"></label><label>关联业务内部编号<input name="entity" value="${esc(q.get('entity')||'')}"></label><button class="button secondary">查询日志</button></form><div class="business-table"><table><thead><tr><th>时间</th><th>操作人</th><th>业务模块</th><th>操作类型</th><th>关联编号</th><th>执行结果</th><th>修改依据</th></tr></thead><tbody>${r.items.map(a=>`<tr><td data-no-i18n>${esc(a.occurred_at)}</td><td data-no-i18n>${esc(a.actor_name||'—')}</td><td>${esc({stocktakes:'库存盘点',stock_adjustments:'库存调整',outbound_corrections:'出库更正',consistency_runs:'一致性检查',loading_orders:'装车与出库',allocations:'备货管理',receipts:'入库管理',users:'账户管理',roles:'角色权限',bundles:'捆包档案'}[a.entity_type]||'业务记录')}</td><td>${this.auditAction(a.action)}<details><summary>操作代码</summary><code data-no-i18n>${esc(a.action)}</code></details></td><td data-no-i18n>${esc(a.entity_id||'—')}</td><td>${a.outcome==='FAILED'?'失败':'成功'}</td><td><details><summary>前后数据</summary><pre data-no-i18n>${esc(JSON.stringify({before:a.before_data,after:a.after_data},null,2))}</pre></details></td></tr>`).join('')}</tbody></table></div><div class="business-toolbar"><button id="v27-audit-prev" ${r.page===1?'disabled':''}>上一页</button><span>${r.page}</span><button id="v27-audit-next" ${r.items.length<r.page_size?'disabled':''}>下一页</button></div><h2>数据库备份执行记录</h2><p class="v27-notice">此处仅查看执行结果，不提供数据库恢复按钮。定时任务需在实际服务器配置并核对首次运行。</p><div class="business-table"><table><thead><tr><th>时间</th><th>执行结果</th><th>备份文件</th><th>恢复验证</th><th>错误码</th></tr></thead><tbody>${backups.items.map(b=>`<tr><td data-no-i18n>${esc(b.finished_at)}</td><td>${b.status==='SUCCESS'?'成功':'失败'}</td><td data-no-i18n>${esc(b.file_name||'—')}</td><td>${b.restore_verified?'已通过':'未执行'}</td><td data-no-i18n>${esc(b.error_code||'—')}</td></tr>`).join('')}</tbody></table></div>`);$('v27-audit-filter').onsubmit=e=>{e.preventDefault();Router.go('/audit?'+new URLSearchParams(new FormData(e.target)));};for(const [id,n] of [['v27-audit-prev',-1],['v27-audit-next',1]])$(id).onclick=()=>{q.set('page',r.page+n);Router.go('/audit?'+q);};}
};
